<div class="modal fade" id="editNavigationModal"><div class="modal-dialog"><div class="modal-content"><form method="POST" id="editNavigationForm">@csrf @method('PUT')<div class="modal-header"><h5>Edit Menu Item</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="location" id="edit-location"><div class="mb-3"><label>Display Text <span class="text-muted">(optional)</span></label><input name="label" id="edit-label" class="form-control" placeholder="Use destination name automatically"></div><div class="mb-3"><label>Destination</label><select name="destination" id="edit-destination" class="form-select js-destination-search">@foreach($destinations as $d)<option value="{{ $d['value'] }}">{{ $d['label'] }}</option>@endforeach</select></div><div class="mb-3"><label>Custom URL</label><input name="custom_url" id="edit-custom_url" class="form-control"><div class="form-text">Only used when Destination is Custom URL.</div></div><div class="mb-3"><label>Footer Column Heading</label><input name="section_label" id="edit-section_label" class="form-control"></div><div class="mb-3"><label>Parent Header Item</label><select name="parent_id" id="edit-parent_id" class="form-select"><option value="">No parent</option>@foreach($items->where('location','header')->whereNull('parent_id') as $parent)<option value="{{ $parent->id }}">{{ $parent->label }}</option>@endforeach</select></div><div class="row g-2 mb-3"><div class="col-6"><label>Icon</label><select name="icon" id="edit-icon" class="form-select">@foreach($icons as $value=>$name)<option value="{{ $value }}">{{ $name }}</option>@endforeach</select></div><div class="col-6"><label>Order</label><input type="number" name="sort_order" id="edit-sort_order" class="form-control" min="0"></div></div><div class="row g-2 mb-3"><div class="col-6"><label>Open</label><select name="target" id="edit-target" class="form-select"><option value="_self">Same tab</option><option value="_blank">New tab</option></select></div><div class="col-6"><label>Style</label><select name="style" id="edit-style" class="form-select"><option value="link">Link</option><option value="button">Button</option></select></div></div><label><input type="checkbox" name="desktop_visible" value="1" id="edit-desktop_visible"> Desktop</label> <label><input type="checkbox" name="mobile_visible" value="1" id="edit-mobile_visible"> Mobile</label> <label><input type="checkbox" name="is_active" value="1" id="edit-is_active"> Active</label></div><div class="modal-footer"><button class="btn el-btn-primary">Update</button></div></form></div></div></div>
