@section('script')<script>
$('.js-destination-search').not('#edit-destination').select2({width:'100%',placeholder:'Type to search destinations'});
$('#edit-destination').select2({width:'100%',dropdownParent:$('#editNavigationModal'),placeholder:'Type to search destinations'});
document.querySelectorAll('.js-edit').forEach(b=>b.onclick=()=>{const x=JSON.parse(b.dataset.item);const f=document.getElementById('editNavigationForm');f.action='{{ url('navigation') }}/'+x.id;['location','label','custom_url','section_label','parent_id','icon','target','style','sort_order'].forEach(k=>document.getElementById('edit-'+k).value=x[k]??'');document.getElementById('edit-destination').value=x.link_type+':'+(x.reference_id??'');$('#edit-destination').trigger('change.select2');['desktop_visible','mobile_visible','is_active'].forEach(k=>document.getElementById('edit-'+k).checked=!!x[k]);bootstrap.Modal.getOrCreateInstance(document.getElementById('editNavigationModal')).show()});
document.querySelectorAll('.js-sortable').forEach(list=>{
 let row=null,nest=false;
 const paint=(target,isChild)=>{list.querySelectorAll('tr').forEach(x=>x.classList.remove('table-info'));if(target&&isChild)target.classList.add('table-info')};
 const save=()=>fetch('{{ route('navigation.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({location:list.dataset.location,items:[...list.querySelectorAll('tr[data-id]')].map(x=>({id:x.dataset.id,parent_id:x.dataset.parent||null}))})});
 list.addEventListener('dragstart',e=>{row=e.target.closest('tr');row?.classList.add('opacity-50')});
 list.addEventListener('dragend',()=>{row?.classList.remove('opacity-50');paint();row=null});
 list.addEventListener('dragover',e=>{e.preventDefault();const over=e.target.closest('tr[data-id]');if(!row||!over||row===over)return;nest=list.dataset.location==='header'&&e.clientX>over.getBoundingClientRect().left+180;paint(over,nest);if(!nest)list.insertBefore(row,over)});
 list.addEventListener('drop',e=>{e.preventDefault();const over=e.target.closest('tr[data-id]');if(!row||!over||row===over)return;let parent=null;if(nest){parent=over.dataset.parent||over.dataset.id;row.dataset.parent=parent;over.after(row)}else{row.dataset.parent=''}const label=row.querySelector('.nav-item-label'),indent=row.querySelector('.nav-indent');label.style.paddingLeft=parent?'42px':'12px';indent.classList.toggle('d-none',!parent);paint();save().then(r=>{if(!r.ok)location.reload()})});
});
</script>@endsection

